with unpacked as (select id, log_ts, level, latency_ms, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, get_json_object(payload_json, '$.duration') as duration_text, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier from app_logs where hour(log_ts) between 6 and 12) select id, level, latency_ms, retry_count, duration_text, avg(duration_sec) over (partition by date_trunc('week', log_ts), level) as log_ts_period_avg_duration_sec, avg(duration_sec) over (partition by level order by latency_ms, id rows between 6 preceding and 1 preceding) as duration_sec_avg_6_prior from unpacked;
